/** MCQ bank - part 2: IAM, cyber operations, technical fundamentals, cloud/AI, consulting judgement, HR & ethics. */

export const CYBER_QUESTIONS = [
  /* ============================ IAM ============================ */
  { id: "a01", d: "iam", lvl: 1, q: "Authentication and authorisation differ in that authentication establishes:", o: ["What you are allowed to do", "Who you are", "What you did", "Where you are connecting from"], a: 1, e: "Authentication is who you are; authorisation is what you're allowed to do. Accounting/auditing records what you did." },
  { id: "a02", d: "iam", lvl: 2, q: "A password plus a security question is:", o: ["Valid MFA", "Not MFA - both are 'something you know'", "Two-factor but not multi-factor", "Phishing-resistant MFA"], a: 1, e: "MFA requires two or more factors from different categories: something you know, have, are (plus contextual signals). A very common interview check." },
  { id: "a03", d: "iam", lvl: 2, q: "Which MFA method is phishing-resistant?", o: ["SMS OTP", "Push notification approval", "FIDO2/WebAuthn passkeys", "Time-based OTP from an authenticator app"], a: 2, e: "Passkeys and smart cards bind the credential to the legitimate domain, so a proxy phishing site cannot relay it. Push and OTP remain vulnerable to real-time relay." },
  { id: "a04", d: "iam", lvl: 2, q: "MFA fatigue attacks are countered by:", o: ["Longer OTP codes", "Number matching and rate limiting", "Disabling MFA on trusted networks", "Increasing session timeout"], a: 1, e: "MFA fatigue is spamming approval prompts until a tired user accepts. Number matching forces the user to read a code from the login screen." },
  { id: "a05", d: "iam", lvl: 2, q: "Role explosion is the classic failure mode of:", o: ["DAC", "MAC", "RBAC", "ABAC"], a: 2, e: "Exceptions breed roles until there are nearly as many roles as users, at which point role-based access stops simplifying anything." },
  { id: "a06", d: "iam", lvl: 2, q: "'A manager in Finance, on a managed device, during business hours, from India' describes which access control model?", o: ["DAC", "RBAC", "ABAC", "MAC"], a: 2, e: "Attribute-based access control evaluates attributes of user, resource, action and environment. More granular and more complex than RBAC." },
  { id: "a07", d: "iam", lvl: 2, q: "The most common failure point in the MOVER flow is:", o: ["No approval trail for the new access", "Old access is never revoked, producing privilege creep", "The HR record is not updated", "The manager is not notified"], a: 1, e: "Over years this produces access creep - a person who has moved through four departments holds the combined rights of all four, often creating a SoD conflict nobody designed." },
  { id: "a08", d: "iam", lvl: 2, q: "When an employee leaves, the recommended first technical action on their directory account is to:", o: ["Delete it immediately", "Disable it, preserving data and audit trail", "Change the password and leave it enabled", "Convert it to a service account"], a: 1, e: "Disable before delete - so data and audit trail are preserved and mailbox access can be delegated. Delete or archive later per the retention policy." },
  { id: "a09", d: "iam", lvl: 3, q: "Which leaver step do organisations most often forget?", o: ["Disabling the AD account", "Rotating shared and service account credentials the person knew", "Recovering the laptop", "Removing the building access card"], a: 1, e: "Otherwise you have removed their account but left them a working password. Also commonly missed: local accounts on legacy systems, personal cloud logins, API keys they generated." },
  { id: "a10", d: "iam", lvl: 2, q: "The authoritative source that should trigger joiner-mover-leaver events is:", o: ["An email from the line manager", "The HR system", "The service desk ticket queue", "Active Directory"], a: 1, e: "If the trigger is an email, the control depends on someone remembering - and that is exactly where it fails." },
  { id: "a11", d: "iam", lvl: 2, q: "OAuth 2.0 is fundamentally:", o: ["An authentication protocol", "An authorisation framework for delegated access", "A federation standard using XML assertions", "A provisioning standard"], a: 1, e: "OIDC adds the authentication layer on top with an ID token. Using OAuth alone for login is a known anti-pattern - an access token proves you were granted access to something, not who you are." },
  { id: "a12", d: "iam", lvl: 2, q: "SCIM is the standard for:", o: ["Single sign-on assertions", "Automated provisioning and de-provisioning of users between systems", "Privileged session recording", "Certificate lifecycle management"], a: 1, e: "System for Cross-domain Identity Management - it is what should automatically revoke SaaS access when a leaver is disabled in the directory." },
  { id: "a13", d: "iam", lvl: 2, q: "An orphan account differs from a dormant account in that an orphan:", o: ["Has an owner but no recent activity", "Has no valid owner at all", "Belongs to a contractor", "Is a shared service account"], a: 1, e: "Orphan = no valid owner, typically a leaver whose de-provisioning failed. Dormant = has an owner but no login activity for a defined period." },
  { id: "a14", d: "iam", lvl: 2, q: "The primary problem with shared or generic accounts is that they:", o: ["Consume extra licences", "Destroy accountability because actions cannot be attributed to an individual", "Cannot use MFA", "Are always excluded from access reviews"], a: 1, e: "Where operationally unavoidable, mitigate with vaulting, check-out logging and session recording." },
  { id: "a15", d: "iam", lvl: 2, q: "Just-in-time privilege differs from standing privilege in that JIT:", o: ["Requires a hardware token", "Grants elevation for a defined window on approval, then automatically revokes", "Applies only to cloud consoles", "Removes the need for session logging"], a: 1, e: "It dramatically reduces the window of exposure compared with permanent elevated access, which is a persistent target." },
  { id: "a16", d: "iam", lvl: 3, q: "Access recertification campaigns show 100% approval and zero revocations across four quarters. The most likely issue is:", o: ["The organisation has unusually stable staffing", "Rubber-stamping - the control operated procedurally but may not be effective", "The reviewers lacked access to the tool", "The population was incomplete"], a: 1, e: "Corroborate by cross-referencing the reviewed population against the HR leaver list, checking movers, and examining whether bulk-approve was the one-click default." },
  { id: "a17", d: "iam", lvl: 2, q: "PAM tooling typically provides all of the following EXCEPT:", o: ["Credential vaulting and automatic rotation", "Session recording and monitoring", "Just-in-time elevation and break-glass access", "Automated data classification"], a: 3, e: "Data classification belongs to the information protection domain, not privileged access management." },
  { id: "a18", d: "iam", lvl: 2, q: "IGA is distinguished from Access Management in that IGA covers:", o: ["Runtime SSO, federation and MFA", "Provisioning workflows, access requests, role management, SoD policy and certification campaigns", "Vaulting and rotation of privileged credentials", "Customer registration and consent"], a: 1, e: "AM is runtime authentication and authorisation; PAM is elevated accounts; CIAM is external customers." },
  { id: "a19", d: "iam", lvl: 2, q: "Zero Trust is best described as:", o: ["A product you can buy from a single vendor", "An architectural strategy in which every request is verified on identity, device and context regardless of network location", "A network segmentation technology", "A compliance requirement under DPDP"], a: 1, e: "Core tenets: verify explicitly, least-privilege and just-in-time access, assume breach. Identity is its control plane. Saying it is a strategy, not a product, shows you can separate marketing from architecture." },
  { id: "a20", d: "iam", lvl: 2, q: "Kerberoasting, golden ticket and pass-the-ticket attacks target:", o: ["SAML", "Kerberos", "OAuth", "SCIM"], a: 1, e: "Kerberos is the ticket-based authentication protocol underpinning Windows domain authentication." },
  { id: "a21", d: "iam", lvl: 2, q: "In most enterprises today, the largest and least-governed identity population is:", o: ["Contractors", "Non-human identities - service accounts, API keys, certificates, workload and agent identities", "Customers", "Privileged administrators"], a: 1, e: "They now outnumber human identities by a large multiple, and are the most commonly ungoverned population." },
  { id: "a22", d: "iam", lvl: 2, q: "A toxic combination where one user can both create a vendor and approve payment to it is a failure of:", o: ["Least privilege only", "Segregation of duties in IAM", "Access certification", "Password policy"], a: 1, e: "Enforced preventively at request time, and detected through periodic conflict analysis." },
  { id: "a23", d: "iam", lvl: 2, q: "'Need to know' differs from 'least privilege' in that need to know:", o: ["Applies only to classified government data", "Restricts access to information required for the specific task, even within an authorised clearance level", "Is a technical control rather than a policy", "Applies only to privileged users"], a: 1, e: "Least privilege is about the minimum rights to do the job; need to know narrows further to the specific information required for a specific task." },
  { id: "a24", d: "iam", lvl: 2, q: "Rolling out MFA where users are resisting is best approached by:", o: ["Enforcing it universally on a single cutover date", "Starting risk-based - privileged accounts, remote access, email, internet-facing systems - with conditional access to reduce friction", "Making it optional indefinitely", "Replacing passwords with security questions"], a: 1, e: "Then pilot with a friendly department, fix enrolment and recovery experience, and if leadership still declines for a population, record a documented risk acceptance at the right level." },
  { id: "a25", d: "iam", lvl: 1, q: "SAML is:", o: ["A provisioning protocol", "An XML-based federation standard where the IdP issues a signed assertion the SP trusts", "A password hashing algorithm", "A directory service"], a: 1, e: "Long-established for enterprise web SSO. OIDC is the modern default for web and mobile." },
  { id: "a26", d: "iam", lvl: 3, q: "A monthly reconciliation between the HR leaver list and active accounts is what kind of control?", o: ["Preventive", "Detective", "Corrective", "Deterrent"], a: 1, e: "It is the detective backstop behind the preventive de-provisioning process - because the preventive process will occasionally fail and you want to find it yourself rather than have an auditor find it." },
  { id: "a27", d: "iam", lvl: 2, q: "SMS-based OTP is the weakest 'something you have' factor primarily because of:", o: ["Cost", "SIM swap and interception", "Battery consumption", "Character limits"], a: 1, e: "It is still far better than no second factor - but where phishing resistance matters, passkeys or smart cards are the right recommendation." },
  { id: "a28", d: "iam", lvl: 2, q: "Which is the correct counter-control for rubber-stamped access reviews?", o: ["Increase review frequency to monthly", "Require an explicit affirmative decision per entitlement, focus campaigns on high-risk access, and track revocation rate as a quality metric", "Move reviews to the security team instead of managers", "Extend the review deadline"], a: 1, e: "Fix the design, not the symptom. Completion alone is a compliance metric; revocation rate tells you whether reviewers are actually reviewing." },

  /* ============================ CYBER OPS: SPM / BCM / PRIVACY / THREAT ============================ */
  { id: "c01", d: "cyberops", lvl: 1, q: "RTO and RPO differ in that RTO measures:", o: ["How much data you can afford to lose", "How long the process can be down before impact is unacceptable", "The outer limit before viability is threatened", "The reduced service level acceptable during disruption"], a: 1, e: "RTO is about time; RPO is about data. RTO answers 'how fast must we be back'; RPO answers 'how much work can we afford to lose'." },
  { id: "c02", d: "cyberops", lvl: 2, q: "MTPD (Maximum Tolerable Period of Disruption) must always be:", o: ["Shorter than the RTO", "Longer than the RTO", "Equal to the RPO", "Set by the IT team"], a: 1, e: "RTO must be shorter than MTPD. A further nuance: RTO plus WRT (work recovery time) must also fall within MTPD." },
  { id: "c03", d: "cyberops", lvl: 3, q: "WRT (Work Recovery Time) refers to:", o: ["Time to restore the system technically", "Time after technical restoration to validate data, clear backlog and return to normal operation", "Time to declare an incident", "Time to notify the regulator"], a: 1, e: "Very few candidates know this. RTO + WRT must be within MTPD." },
  { id: "c04", d: "cyberops", lvl: 2, q: "The foundation of any BCM programme is the:", o: ["Disaster recovery plan", "Business Impact Analysis", "Crisis communication plan", "Risk register"], a: 1, e: "The BIA identifies critical processes, impact over time, recovery objectives and dependencies. Strategy and plans follow from it." },
  { id: "c05", d: "cyberops", lvl: 2, q: "Synchronous replication gives an RPO of effectively zero but:", o: ["Requires tape media", "Is distance-limited by latency", "Cannot be used with databases", "Does not protect against hardware failure"], a: 1, e: "Asynchronous replication tolerates distance with a small data-loss window; snapshots and backups give RPOs measured in hours." },
  { id: "c06", d: "cyberops", lvl: 2, q: "The 3-2-1 backup rule extended for the ransomware era becomes 3-2-1-1-0, where the extra elements are:", o: ["One cloud copy and zero cost", "One immutable or offline copy and zero errors on restore verification", "One encrypted copy and zero retention limit", "One vendor and zero downtime"], a: 1, e: "Three copies, two media, one off-site, one immutable/offline, zero restore errors." },
  { id: "c07", d: "cyberops", lvl: 2, q: "Which exercise type gives the highest assurance but carries the highest risk?", o: ["Tabletop", "Simulation", "Parallel test", "Full interruption"], a: 3, e: "Production is actually failed over. Usually only in mature organisations with a maintenance window." },
  { id: "c08", d: "cyberops", lvl: 2, q: "The most common weakness found in a BCM programme is:", o: ["Plans that do not name an invocation authority", "Plans that exist but have never been tested end to end, especially restoration", "Insufficient hot site capacity", "Lack of ISO 22301 certification"], a: 1, e: "Backup jobs report success but nobody has proven a full restore within RTO; the call tree lists people who left; the plan is stored on the file share the ransomware encrypted." },
  { id: "c09", d: "cyberops", lvl: 3, q: "In the first hours of a ransomware incident, affected systems should ideally be:", o: ["Powered off immediately to stop encryption", "Isolated from the network without powering off, to preserve memory and volatile evidence", "Reimaged immediately", "Left connected while forensics is arranged"], a: 1, e: "Isolate rather than power off where possible. Also verify the backups are intact and isolated - sophisticated ransomware targets backups first, and if they are encrypted every subsequent decision changes." },
  { id: "c10", d: "cyberops", lvl: 2, q: "In a ransomware incident, discovering that data was exfiltrated before encryption is critical because it:", o: ["Increases the ransom", "Converts an availability incident into a data breach with notification obligations", "Means backups are unusable", "Proves the attacker is still present"], a: 1, e: "That changes the regulatory picture: in India, CERT-In's six-hour window plus DPDP obligations to the Data Protection Board and affected individuals." },
  { id: "c11", d: "cyberops", lvl: 2, q: "Recovering after ransomware should be done into:", o: ["The same domain to preserve configuration", "A clean, rebuilt environment - restoring into the compromised domain simply re-infects you", "A cloud environment only", "Whichever is fastest"], a: 1, e: "Rebuild rather than restore where integrity is uncertain, and recover in the priority order the BIA already defined." },
  { id: "c12", d: "cyberops", lvl: 2, q: "The decision on whether to pay a ransom is:", o: ["A technical decision for the incident responder", "A business, legal and regulatory decision, with sanctions exposure to consider", "Made by the insurer alone", "Prohibited in all jurisdictions"], a: 1, e: "Keeping the payment decision out of the technical lane is a mark of a strong answer." },
  { id: "c13", d: "cyberops", lvl: 1, q: "A KRI differs from a KPI in that a KRI is:", o: ["Measured monthly rather than quarterly", "Forward-looking and signals rising exposure before an incident", "Reported only to the audit committee", "Always quantitative"], a: 1, e: "KPI: patch compliance is 94%. KRI: internet-facing systems with critical unpatched vulnerabilities older than 30 days, trending upward. Boards need KRIs; operations teams live on KPIs." },
  { id: "c14", d: "cyberops", lvl: 2, q: "In the policy hierarchy, a document stating 'Data classified Confidential shall be encrypted at rest using AES-256' is a:", o: ["Policy", "Standard", "Procedure", "Guideline"], a: 1, e: "Policy = what and why (board-approved, durable). Standard = what specifically (technology-bound). Procedure = how, step by step. Guideline = recommended, not mandatory." },
  { id: "c15", d: "cyberops", lvl: 2, q: "Why should policies avoid naming specific products or versions?", o: ["It breaches vendor confidentiality", "They become stale within a year and then nobody trusts the framework", "Auditors are not permitted to see product names", "It creates a procurement conflict"], a: 1, e: "Keep technology specifics in standards and baselines; keep policy durable and principle-based." },
  { id: "c16", d: "cyberops", lvl: 2, q: "Which metric actually proves recoverability?", o: ["Backup job success rate", "Backup restoration test success", "Storage utilisation", "Replication lag"], a: 1, e: "Backup success rate alone proves nothing about whether you can restore within the RTO." },
  { id: "c17", d: "cyberops", lvl: 2, q: "In a phishing simulation programme, the more meaningful metric is the:", o: ["Click rate", "Report rate", "Open rate", "Time to delete"], a: 1, e: "The report rate measures whether your human sensor network works - which is the capability you actually want to build." },
  { id: "c18", d: "cyberops", lvl: 2, q: "Security and privacy differ in that privacy asks:", o: ["Whether the data is encrypted", "Whether we should have the data at all, whether the person knows, and whether we use it as promised", "Whether access is logged", "Whether the data is backed up"], a: 1, e: "You can hold personal data in a perfectly encrypted database and still be in breach because you had no lawful basis to collect it." },
  { id: "c19", d: "cyberops", lvl: 3, q: "Pseudonymised data:", o: ["Falls outside data protection law entirely", "Remains personal data because it can be re-identified using information held separately", "Is the same as anonymised data", "Cannot be used for analytics"], a: 1, e: "Anonymised data cannot be re-identified by any reasonable means and generally falls outside the law. Candidates get this wrong constantly." },
  { id: "c20", d: "cyberops", lvl: 2, q: "Tokenisation is commonly used for card data because it:", o: ["Is faster than encryption", "Substitutes a non-sensitive value with the mapping held in a separate vault, removing systems from PCI DSS scope", "Satisfies the right to erasure", "Provides non-repudiation"], a: 1, e: "Masking, by contrast, obscures data for display or non-production use - a support agent sees only the last four digits." },
  { id: "c21", d: "cyberops", lvl: 2, q: "DLP is normally deployed in monitor mode first because:", o: ["Licensing is cheaper", "Blocking on day one produces false positives that break business processes and destroy the programme's credibility", "Regulators require a monitoring period", "Encryption must be enabled first"], a: 1, e: "Tune on real traffic before you enforce." },
  { id: "c22", d: "cyberops", lvl: 2, q: "A ROPA is:", o: ["A risk and opportunity portfolio assessment", "A record of processing activities - what personal data you hold, why, from whom, shared with whom, and for how long", "A regulator-issued processing authorisation", "A retention of personal archives policy"], a: 1, e: "It is the output of data discovery and mapping, and the foundation of a privacy programme." },
  { id: "c23", d: "cyberops", lvl: 2, q: "A DPIA is required for:", o: ["All processing of personal data", "High-risk processing - new systems, profiling, large-scale or sensitive data, new technologies", "Only cross-border transfers", "Only processing by Significant Data Fiduciaries"], a: 1, e: "It assesses necessity, proportionality, risks to individuals and mitigations." },
  { id: "c24", d: "cyberops", lvl: 3, q: "In consent management implementations, the step that most commonly fails is:", o: ["Capturing consent at sign-up", "Propagating withdrawal downstream to processors, analytics and marketing tools", "Displaying the privacy notice", "Recording the consent timestamp"], a: 1, e: "Withdrawal must be as easy as giving consent - and it must actually reach every system that received the data. Usually an integration problem nobody scopes." },
  { id: "c25", d: "cyberops", lvl: 2, q: "Privacy by design's 'full functionality' principle means:", o: ["All features must be enabled by default", "Privacy and utility are positive-sum, not a false trade-off", "The system must work offline", "Users control every setting"], a: 1, e: "The consulting point: retrofitting privacy into a live system costs far more than designing it in, which is why privacy review belongs as a gate in the development lifecycle." },
  { id: "c26", d: "cyberops", lvl: 1, q: "A SIEM primarily:", o: ["Automates response playbooks", "Aggregates and correlates logs into alerts", "Monitors endpoint behaviour", "Scans for vulnerabilities"], a: 1, e: "SOAR automates the response playbooks around the alerts a SIEM produces." },
  { id: "c27", d: "cyberops", lvl: 2, q: "UEBA is the primary detection approach for:", o: ["Known malware signatures", "Insider threat and compromised credentials, where nothing overtly malicious executes", "Network DDoS", "Vulnerable dependencies"], a: 1, e: "User and Entity Behaviour Analytics baselines normal behaviour and flags deviation." },
  { id: "c28", d: "cyberops", lvl: 2, q: "XDR extends EDR by:", o: ["Adding vulnerability scanning", "Correlating across endpoint, network, identity, email and cloud", "Providing legal hold capability", "Replacing the SIEM entirely"], a: 1, e: "EDR monitors endpoint behaviour and enables isolation; XDR widens the correlation surface." },
  { id: "c29", d: "cyberops", lvl: 2, q: "The correct ordering of event, alert, incident and breach is:", o: ["Alert → event → incident → breach", "Event → alert → incident → breach", "Event → incident → alert → breach", "Incident → event → alert → breach"], a: 1, e: "An event is any observable occurrence; an alert matched a detection rule; an incident is validated harm or policy violation; a breach is a confirmed compromise of data confidentiality. Not every incident is a breach." },
  { id: "c30", d: "cyberops", lvl: 2, q: "Declaring an incident matters operationally because it:", o: ["Triggers the insurance payout", "Starts clocks - internal escalation and potentially regulatory notification timelines", "Requires the SOC to stop other work", "Automatically notifies customers"], a: 1, e: "In India that means the CERT-In six-hour window, and potentially DPDP obligations." },
  { id: "c31", d: "cyberops", lvl: 1, q: "The NIST SP 800-61 incident response phases are:", o: ["Identify, protect, detect, respond, recover", "Preparation; detection and analysis; containment, eradication and recovery; post-incident activity", "Prevent, detect, contain, report", "Plan, do, check, act"], a: 1, e: "SANS describes six phases - preparation, identification, containment, eradication, recovery, lessons learned. Either is acceptable; know that both exist." },
  { id: "c32", d: "cyberops", lvl: 2, q: "A vulnerability assessment differs from a penetration test in that a VA:", o: ["Is manual and goal-directed", "Is broad, largely automated scanning that identifies known weaknesses without exploitation", "Requires a red team", "Always includes social engineering"], a: 1, e: "\"A scan tells you which doors are unlocked; a penetration test tells you what someone can actually do once through one.\"" },
  { id: "c33", d: "cyberops", lvl: 2, q: "Purple teaming is valuable because it:", o: ["Is cheaper than a vulnerability scan", "Has red and blue work together to measure and improve detection coverage", "Replaces the need for a SOC", "Tests only physical security"], a: 1, e: "The highest learning value per rupee. A red team tests detection and response without the defenders knowing; purple team deliberately measures and improves it." },
  { id: "c34", d: "cyberops", lvl: 2, q: "Threat hunting is best described as:", o: ["Reviewing every SIEM alert manually", "Hypothesis-driven proactive search for adversary activity that automated detection missed", "Purchasing threat intelligence feeds", "Scanning for known CVEs"], a: 1, e: "'If an attacker were using this technique, what would I see in the data?'" },
  { id: "c35", d: "cyberops", lvl: 3, q: "A SOC produces 5,000 alerts a day against a capacity of 200. The first and cheapest intervention is to:", o: ["Hire more L1 analysts", "Tune - a handful of rules usually generate the majority of volume and false positives", "Buy a SOAR platform", "Replace the SIEM"], a: 1, e: "Then add context (asset criticality, privilege, threat intel) so triage is faster, then automate the repetitive path, then fix the upstream control gap." },
  { id: "c36", d: "cyberops", lvl: 2, q: "Grey box penetration testing is usually most cost-effective because:", o: ["It requires fewer testers", "The tester spends time finding flaws rather than mapping the environment", "It excludes the application layer", "It does not require a scope agreement"], a: 1, e: "Black box = no prior knowledge; white box = full information including source; grey box = partial, typically credentialed user access." },
  { id: "c37", d: "cyberops", lvl: 2, q: "Deception technology such as canary tokens produces high-fidelity alerts because:", o: ["It uses machine learning", "Legitimate users never touch the decoy, so any interaction is meaningful", "It is deployed only in the DMZ", "It integrates with the SIEM"], a: 1, e: "Low volume, very low false positive rate - the opposite problem to most detection sources." },
  { id: "c38", d: "cyberops", lvl: 2, q: "Vulnerability prioritisation should use:", o: ["CVSS score alone", "Exploitability and business context alongside severity", "Asset age", "Alphabetical order of the affected product"], a: 1, e: "A high CVSS on an isolated test box matters less than a medium on an internet-facing system holding regulated data." },

  /* ============================ TECHNICAL FUNDAMENTALS ============================ */
  { id: "n01", d: "technical", lvl: 1, q: "Hashing provides:", o: ["Confidentiality", "Integrity", "Availability", "Non-repudiation on its own"], a: 1, e: "Hashing is one-way and fixed-length. It is not encryption and cannot be reversed. Encryption provides confidentiality; a digital signature adds authenticity and non-repudiation." },
  { id: "n02", d: "technical", lvl: 2, q: "Base64 encoding provides:", o: ["Strong confidentiality", "No security at all - it is for data representation and is trivially reversible", "Integrity verification", "Key exchange"], a: 1, e: "Candidates who say 'we encoded the password' have made a serious conceptual error, and interviewers use this to sort quickly." },
  { id: "n03", d: "technical", lvl: 2, q: "Passwords should be stored using:", o: ["AES-256 encryption", "SHA-256 hashing", "A slow, salted adaptive hash such as bcrypt, scrypt or Argon2", "Base64 with a secret prefix"], a: 2, e: "Encryption is reversible; a plain fast hash is brute-forceable by design. The salt defeats rainbow tables and bulk cracking; the work factor makes each guess expensive." },
  { id: "n04", d: "technical", lvl: 2, q: "A salt achieves:", o: ["Faster hashing", "Identical passwords producing different hashes, defeating precomputed tables", "Reversible encryption", "Key escrow"], a: 1, e: "It is unique per user and stored alongside the hash - it is not a secret, it is an anti-precomputation measure." },
  { id: "n05", d: "technical", lvl: 2, q: "TLS uses a hybrid model in which:", o: ["Only symmetric encryption is used", "Asymmetric cryptography agrees a session key and symmetric encryption protects the data", "Only asymmetric encryption is used", "Hashing replaces encryption"], a: 1, e: "Asymmetric solves key distribution but is slow for bulk data; symmetric is fast. TLS gets both." },
  { id: "n06", d: "technical", lvl: 2, q: "Perfect forward secrecy ensures that:", o: ["Certificates never expire", "Compromise of the long-term private key does not expose past recorded sessions", "Data at rest is encrypted", "Keys are escrowed with a third party"], a: 1, e: "Provided by ephemeral Diffie-Hellman key exchange, which generates a fresh session key each time." },
  { id: "n07", d: "technical", lvl: 2, q: "'Harvest now, decrypt later' describes:", o: ["Ransomware double extortion", "Adversaries storing encrypted traffic today to decrypt once quantum capability arrives", "Credential stuffing", "Log tampering"], a: 1, e: "It is the near-term practical risk driving post-quantum cryptography migration planning." },
  { id: "n08", d: "technical", lvl: 2, q: "A digital signature provides integrity, authenticity and:", o: ["Confidentiality", "Non-repudiation", "Availability", "Forward secrecy"], a: 1, e: "It is a hash of the message encrypted with the sender's private key; anyone with the public key can verify it." },
  { id: "n09", d: "technical", lvl: 1, q: "The OSI layers from 7 to 1 are:", o: ["Application, presentation, session, transport, network, data link, physical", "Application, session, presentation, network, transport, data link, physical", "Physical, data link, network, transport, session, presentation, application", "Application, transport, network, session, presentation, data link, physical"], a: 0, e: "Mnemonic top down: All People Seem To Need Data Processing." },
  { id: "n10", d: "technical", lvl: 2, q: "A SYN flood exploits:", o: ["UDP's lack of a handshake", "TCP's three-way handshake, by exhausting half-open connection state", "DNS recursion", "ARP caching"], a: 1, e: "TCP's handshake is SYN, SYN-ACK, ACK. UDP is instead the preferred vehicle for reflection and amplification DDoS because source addresses are easily spoofed." },
  { id: "n11", d: "technical", lvl: 1, q: "Ports 445 and 3389 are:", o: ["HTTPS and DNS", "SMB and RDP", "SSH and LDAP", "SMTP and IMAP"], a: 1, e: "Both exposed to the internet are among the most common initial access vectors - the first things to look for on an external review." },
  { id: "n12", d: "technical", lvl: 2, q: "A stateful firewall differs from a packet filter in that it:", o: ["Inspects application-layer content", "Tracks connection state so return traffic for an established session is permitted", "Terminates TLS", "Blocks based on user identity"], a: 1, e: "Application awareness, user identity and TLS inspection are next-generation firewall features." },
  { id: "n13", d: "technical", lvl: 2, q: "The trade-off between IDS and IPS is that:", o: ["An IDS is more expensive", "A false positive on an IDS creates noise; on an IPS it creates an outage", "An IPS cannot detect encrypted traffic", "An IDS sits in line"], a: 1, e: "An IDS detects and alerts out of band; an IPS sits in line and can block." },
  { id: "n14", d: "technical", lvl: 2, q: "A DMZ exists to:", o: ["Encrypt all internal traffic", "Host internet-facing services in a segmented zone so their compromise does not immediately reach internal systems", "Provide redundant internet links", "Store backups offsite"], a: 1, e: "Micro-segmentation takes the same logic to workload level and is the network expression of Zero Trust." },
  { id: "n15", d: "technical", lvl: 2, q: "A WAF should be understood as:", o: ["A replacement for secure coding", "A compensating control that inspects HTTP/S for application-layer attacks", "A network-layer packet filter", "An endpoint agent"], a: 1, e: "It is not a substitute for parameterised queries and output encoding." },
  { id: "n16", d: "technical", lvl: 2, q: "Zero Trust Network Access is replacing traditional VPN because ZTNA:", o: ["Is cheaper to licence", "Grants access to specific applications rather than placing the device on the network", "Does not require authentication", "Works only in the cloud"], a: 1, e: "A VPN that drops a device onto the internal network gives far more lateral reach than the user actually needs." },
  { id: "n17", d: "technical", lvl: 2, q: "The definitive fix for SQL injection is:", o: ["Input validation", "A web application firewall", "Parameterised queries / prepared statements", "Escaping single quotes"], a: 2, e: "Parameterised queries keep data as data regardless of content. Input validation and WAFs are supporting controls, not the fix." },
  { id: "n18", d: "technical", lvl: 2, q: "Stored XSS differs from reflected XSS in that stored XSS:", o: ["Occurs entirely in client-side code", "Persists in the database and is served to every viewer", "Requires the victim to click a crafted link", "Affects only the attacker's own session"], a: 1, e: "Reflected XSS comes back in a response to a crafted link; DOM-based XSS occurs entirely in client-side code." },
  { id: "n19", d: "technical", lvl: 2, q: "CSRF works because:", o: ["The application does not validate input", "The browser automatically attaches the victim's session to a request they did not intend to make", "Session tokens are predictable", "TLS is not enabled"], a: 1, e: "Fixed with anti-CSRF tokens, the SameSite cookie attribute, and re-authentication for sensitive actions." },
  { id: "n20", d: "technical", lvl: 3, q: "SSRF is dangerous primarily because it lets an attacker:", o: ["Read arbitrary files from the web root", "Make the application reach internal systems and cloud metadata services on their behalf", "Inject scripts into other users' browsers", "Escalate to domain admin directly"], a: 1, e: "Control: allow-list outbound destinations, block internal address ranges, disable unused URL schemes." },
  { id: "n21", d: "technical", lvl: 2, q: "Changing an ID in a URL to view another customer's record is:", o: ["Injection", "Broken access control (insecure direct object reference)", "Security misconfiguration", "Cryptographic failure"], a: 1, e: "Control: enforce authorisation server-side on every request, deny by default, and test with multiple user roles." },
  { id: "n22", d: "technical", lvl: 2, q: "SAST, DAST and SCA respectively analyse:", o: ["Source code, the running application, third-party dependencies", "The network, the endpoint, the cloud", "Static data, dynamic data, structured data", "Servers, applications, containers"], a: 0, e: "Shift left means moving these earlier, because the cost of fixing a flaw rises by orders of magnitude from design to production." },
  { id: "n23", d: "technical", lvl: 2, q: "'Insecure design' in the OWASP categories refers to flaws that:", o: ["Result from a missing patch", "Exist in the design itself and cannot be fixed by implementation quality - e.g. a password reset flow with no rate limiting", "Are introduced by third-party libraries", "Occur only in legacy systems"], a: 1, e: "Control: threat modelling during design, security requirements, secure design patterns." },
  { id: "n24", d: "technical", lvl: 1, q: "A worm differs from a virus in that a worm:", o: ["Requires a host file and user action", "Self-propagates across networks without user action", "Only affects Windows systems", "Is always fileless"], a: 1, e: "Hence rapid, wide outbreaks." },
  { id: "n25", d: "technical", lvl: 2, q: "Double extortion ransomware means the attacker:", o: ["Demands payment twice", "Exfiltrates data first, then encrypts - so restoring from backup does not remove the leverage", "Encrypts both production and backups", "Attacks two organisations simultaneously"], a: 1, e: "Triple extortion adds DDoS or direct pressure on the victim's customers." },
  { id: "n26", d: "technical", lvl: 2, q: "Fileless malware evades signature-based detection because it:", o: ["Uses polymorphic encryption", "Operates in memory using legitimate system tools such as PowerShell and WMI", "Hides in the boot sector", "Runs only at night"], a: 1, e: "'Living off the land' - which is precisely why behavioural EDR matters." },
  { id: "n27", d: "technical", lvl: 2, q: "Business email compromise is notable because it:", o: ["Always involves ransomware", "Uses no malware at all, so the control is a process control - out-of-band verification of bank detail changes", "Targets only large enterprises", "Exploits a specific CVE"], a: 1, e: "Frequently the single largest financial cyber loss for mid-size companies." },
  { id: "n28", d: "technical", lvl: 2, q: "Password spraying differs from credential stuffing in that spraying:", o: ["Replays credentials breached elsewhere", "Tries one common password against many accounts to avoid lockout thresholds", "Uses a dictionary against one account", "Requires prior network access"], a: 1, e: "Both are countered by MFA, breached-password checks, rate limiting and anomaly detection." },
  { id: "n29", d: "technical", lvl: 2, q: "A zero-day is countered primarily by:", o: ["Faster patching", "Defence in depth, virtual patching, segmentation and rapid detection", "Antivirus signature updates", "Password rotation"], a: 1, e: "By definition there is no patch available, so prevention through patching is not an option." },
  { id: "n30", d: "technical", lvl: 2, q: "Horizontal privilege escalation means:", o: ["Gaining administrator rights", "Accessing another user's data at the same privilege level", "Moving between network segments", "Escaping a container"], a: 1, e: "Vertical escalation is gaining higher rights than assigned." },
  { id: "n31", d: "technical", lvl: 2, q: "Lateral movement is best countered by:", o: ["Perimeter firewalls alone", "Segmentation, PAM, and detection of anomalous authentication", "Longer passwords", "Disabling USB ports"], a: 1, e: "Initial access is usually mundane; the damage comes from undetected movement over time." },
  { id: "n32", d: "technical", lvl: 2, q: "'Fail secure' as a design principle means:", o: ["The system logs all failures", "A failure should deny rather than allow", "The system fails over to a secondary site", "Errors are hidden from users"], a: 1, e: "Related principles: least privilege, separation of duties, minimise attack surface, assume breach." },
  { id: "n33", d: "technical", lvl: 2, q: "Which is a genuine example of confidentiality conflicting with availability?", o: ["Encrypting data in transit slows the network", "Keys held in a single tightly restricted HSM protect data perfectly but may be unavailable during a disaster", "Firewalls block legitimate traffic occasionally", "Logging consumes disk space"], a: 1, e: "Key escrow and recovery procedures are the balance. Another example: aggressive account lockout protects against brute force but creates a self-inflicted DoS vector." },
  { id: "n34", d: "technical", lvl: 2, q: "DNS is abused by attackers for:", o: ["Privilege escalation", "Command and control, and exfiltration via DNS tunnelling", "Password cracking", "Physical access"], a: 1, e: "DNS filtering that blocks resolution of known-malicious domains is a cheap, high-value control." },
  { id: "n35", d: "technical", lvl: 1, q: "Non-repudiation is supported by:", o: ["Encryption at rest", "Digital signatures and tamper-evident audit logs", "Network segmentation", "Redundant power supply"], a: 1, e: "It ensures a party cannot credibly deny having performed an action - which is precisely what shared accounts destroy." },
  { id: "n36", d: "technical", lvl: 2, q: "TCP is preferred over UDP for:", o: ["DNS queries and VoIP", "Web, email, file transfer and database traffic", "Video streaming", "DHCP"], a: 1, e: "TCP guarantees delivery, ordering and retransmission at the cost of overhead. UDP is best-effort and faster." },
  { id: "n37", d: "technical", lvl: 2, q: "ARP spoofing and VLAN hopping are attacks at which OSI layer?", o: ["Layer 1", "Layer 2 (data link)", "Layer 3 (network)", "Layer 4 (transport)"], a: 1, e: "Layer 2 deals with framing, MAC addressing and local delivery - Ethernet, switches, ARP, VLANs." },
  { id: "n38", d: "technical", lvl: 2, q: "HMAC is used to:", o: ["Encrypt bulk data", "Prove integrity and authenticity of a message using a shared secret key", "Generate certificates", "Derive session keys"], a: 1, e: "Commonly used in API request signing." },
  { id: "n39", d: "technical", lvl: 2, q: "Which hashing algorithms are considered broken for security use?", o: ["SHA-256 and SHA-3", "MD5 and SHA-1", "bcrypt and Argon2", "AES and ChaCha20"], a: 1, e: "AES and ChaCha20 are ciphers, not hashes; bcrypt and Argon2 are password-hashing functions." },
  { id: "n40", d: "technical", lvl: 3, q: "API-specific risks that differ from classic web app risks include:", o: ["Broken object-level authorisation and excessive data exposure", "Buffer overflows", "Physical tampering", "Weak TLS ciphers only"], a: 0, e: "Plus missing rate limiting and undocumented shadow or zombie endpoints. APIs are now a larger attack surface than web UIs for many organisations." },

  /* ============================ CLOUD & AI ============================ */
  { id: "u01", d: "cloudai", lvl: 1, q: "Under the shared responsibility model, the customer is ALWAYS responsible for:", o: ["Hypervisor patching", "Their data, their identities and access, and their configuration", "Physical data centre security", "Network fabric availability"], a: 1, e: "The provider is responsible for security OF the cloud; the customer for security IN the cloud - regardless of service model." },
  { id: "u02", d: "cloudai", lvl: 2, q: "In SaaS, the customer still manages:", o: ["The application code", "Data, identity and access, configuration within the application, and usage", "The operating system", "The runtime"], a: 1, e: "And crucially, backups of their own data - SaaS providers protect their platform, not against a customer deleting their own records." },
  { id: "u03", d: "cloudai", lvl: 2, q: "The dominant cause of cloud data exposure is:", o: ["Provider breaches", "Customer misconfiguration - public storage, over-permissive policies, disabled logging", "Zero-day exploits", "Insider threat at the provider"], a: 1, e: "It is almost always a configuration error rather than a provider breach." },
  { id: "u04", d: "cloudai", lvl: 2, q: "CSPM tooling is used to:", o: ["Protect workloads at runtime", "Continuously check cloud configuration against a baseline", "Manage entitlements and permissions", "Scan container images"], a: 1, e: "CWPP is workload protection, CIEM is entitlement management, CNAPP is the consolidated platform, and IaC scanning catches misconfiguration before deployment." },
  { id: "u05", d: "cloudai", lvl: 2, q: "CIEM addresses which specific cloud problem?", o: ["Data residency", "Over-privileged identities - wildcard permissions, long-lived keys, unused entitlements", "Cost overruns", "Log retention"], a: 1, e: "Cloud Infrastructure Entitlement Management. In the cloud, the console is the new perimeter." },
  { id: "u06", d: "cloudai", lvl: 3, q: "A client asks for the correct sequence when migrating to cloud. The best advice is:", o: ["Migrate first and secure afterwards to prove value quickly", "Landing zone design - accounts, network, identity, logging, guardrails - before the first workload moves", "Migrate the most critical system first", "Wait until a CSPM tool is procured"], a: 1, e: "Securing afterwards is how misconfiguration debt accumulates at scale." },
  { id: "u07", d: "cloudai", lvl: 2, q: "If control-plane audit logs were never enabled, the consequence during an investigation is that:", o: ["Costs cannot be attributed", "There is nothing to investigate with", "Backups cannot be restored", "Identities cannot be disabled"], a: 1, e: "Logging and monitoring must be enabled from day one, not after the first incident." },
  { id: "u08", d: "cloudai", lvl: 2, q: "The defining new weakness of LLM applications, especially agentic ones, is:", o: ["Model inversion", "Prompt injection - instructions hidden in data that the model processes as commands", "Slow inference", "Token cost"], a: 1, e: "Especially dangerous where the agent has tool access and can actually act on the injected instruction." },
  { id: "u09", d: "cloudai", lvl: 2, q: "Shadow AI refers to:", o: ["AI used by attackers", "Unsanctioned AI tools adopted departmentally, invisible to governance", "Models trained on synthetic data", "Open source models"], a: 1, e: "It is primarily a data leakage route - staff pasting confidential or personal data into public tools." },
  { id: "u10", d: "cloudai", lvl: 3, q: "The genuinely new governance control that agentic AI demands is:", o: ["Stronger encryption", "Treating an AI agent as a non-human identity with permissions requiring identity governance", "Longer retention of prompts", "Separate network segments for GPUs"], a: 1, e: "Most organisations have no governance for non-human identities at all - which is what makes this the sharp point to raise." },
  { id: "u11", d: "cloudai", lvl: 2, q: "Which governance reference is specifically an AI management system standard?", o: ["NIST AI RMF", "ISO/IEC 42001", "EU AI Act", "OWASP Top 10 for LLM Applications"], a: 1, e: "NIST AI RMF is a risk management framework; the EU AI Act is legislation with risk-tiered obligations; OWASP LLM Top 10 is a vulnerability taxonomy." },
  { id: "u12", d: "cloudai", lvl: 2, q: "The defensible position on AI's effect on security is that AI:", o: ["Will replace security analysts", "Changes nothing fundamental", "Shifts the economics - cheaper, more scalable attacks and more efficient triage, so a faster arms race", "Is primarily a compliance issue"], a: 2, e: "Both extreme positions are lazy and interviewers hear them constantly." },
  { id: "u13", d: "cloudai", lvl: 2, q: "AI as a threat multiplier most directly invalidates which long-standing security advice?", o: ["Use a password manager", "Look for bad grammar and spelling to spot phishing", "Patch promptly", "Back up regularly"], a: 1, e: "Fluent, personalised phishing at scale is now trivial to produce." },
  { id: "u14", d: "cloudai", lvl: 2, q: "In IaaS, the customer is responsible for:", o: ["Only data and identity", "OS, patching, runtime, applications, data, identity and configuration", "Nothing beyond usage", "The virtualisation layer"], a: 1, e: "PaaS removes OS and runtime from the customer's list; SaaS removes nearly everything except data, identity, in-app configuration and usage." },
  { id: "u15", d: "cloudai", lvl: 2, q: "Secrets committed to code repositories are best prevented by:", o: ["Longer key lengths", "Pre-commit scanning, secret management services and short-lived credentials", "More frequent rotation only", "Private repositories"], a: 1, e: "A private repository is not a control - it only narrows who can read the secret, and repositories get forked, cloned and leaked." },
  { id: "u16", d: "cloudai", lvl: 2, q: "A client assumes their SaaS provider backs up their data against accidental deletion. Your response:", o: ["Confirm it - providers always do", "Explain that providers protect their platform, not against the customer deleting their own data; SaaS backup is usually the customer's problem", "Recommend switching providers", "Advise increasing the retention setting only"], a: 1, e: "It is usually nobody's job, which is exactly why it is worth raising." },

  /* ============================ CONSULTING JUDGEMENT ============================ */
  { id: "j01", d: "consulting", lvl: 2, q: "In the four-move pattern for structuring a consulting answer, the move candidates most often skip is:", o: ["Clarify", "Structure - saying out loud how you will break the problem down before solving any part", "Analyse", "Recommend"], a: 1, e: "And it is the one being scored." },
  { id: "j02", d: "consulting", lvl: 2, q: "Which phrase best converts guessing into professional practice?", o: ["\"I think it's probably...\"", "\"I'm going to assume X - tell me if that's wrong.\"", "\"It depends.\"", "\"I'd need more information.\""], a: 1, e: "Stating assumptions as assumptions is what consultants actually do. Adding \"the thing that would change my recommendation is...\" reads as seniority." },
  { id: "j03", d: "consulting", lvl: 2, q: "Asked 'why did this control fail?', the default structure to reach for is:", o: ["Prevent, detect, respond", "People, process, technology (plus governance and data for depth)", "Short, medium, long term", "Likelihood × impact"], a: 1, e: "Use NIST CSF functions for 'assess their posture'; short/medium/long for recommendations; likelihood × impact for prioritisation." },
  { id: "j04", d: "consulting", lvl: 2, q: "A client asks you mid-engagement to review something outside scope. The correct response is to:", o: ["Do it quietly if it is small", "Be helpful, understand the driver, and say you will take it to your manager today and come back with how to handle it", "Refuse and cite the engagement letter", "Agree a fee on the spot"], a: 1, e: "Doing it eats the budget, creates an expectation that scope is flexible, and creates a real question later about what you did and did not look at - a risk to the firm, not just the budget." },
  { id: "j05", d: "consulting", lvl: 2, q: "Asked to complete 40 controls by tomorrow when you can realistically do 25, the best answer is to:", o: ["Work through the night to finish all 40", "Raise it immediately with a prioritised plan and options, refusing to cut sample sizes without basis", "Complete 25 and say nothing", "Ask a colleague to sign off the rest"], a: 1, e: "Most candidates answer 'I'd work late', which misses the point. A control marked as tested when it was not properly tested is a much bigger problem than a missed deadline." },
  { id: "j06", d: "consulting", lvl: 2, q: "Guesstimate questions are asked primarily to test whether you:", o: ["Can do arithmetic quickly", "State your approach, use round numbers, state assumptions, sanity-check, and name the sensitive assumption", "Know industry statistics", "Can reach the exact number"], a: 1, e: "End by naming the lever - it converts an arithmetic exercise into a business insight." },
  { id: "j07", d: "consulting", lvl: 2, q: "A board asks 'we spent ₹10 crore - are we safer?'. The strongest structure is:", o: ["Yes, and here are the projects delivered", "What changed in exposure, what changed in capability, what the residual risk is now - then the next decision", "A list of controls implemented", "Benchmarking against competitors"], a: 1, e: "Boards remember the last sentence, so close with what you would spend the next rupee on and why." },
  { id: "j08", d: "consulting", lvl: 3, q: "A vendor's SOC 2 report arrives. The correct action is to:", o: ["File it as evidence of assurance", "Check the period covers the right window, the scope includes the service you use, read the Section IV exceptions, and read the CUECs", "Forward it to the regulator", "Request a fresh bespoke questionnaire anyway"], a: 1, e: "The CUECs are the things you have to do for their controls to work - a detail few people at any level get right." },
  { id: "j09", d: "consulting", lvl: 2, q: "Silence while thinking in an interview is best handled by:", o: ["Talking continuously until a structure appears", "Saying 'give me a few seconds to structure this' and then taking them", "Asking the interviewer to repeat the question", "Moving to a different question"], a: 1, e: "Unstructured talking while you hope a structure appears is the failure mode being tested." },
  { id: "j10", d: "consulting", lvl: 2, q: "In a group discussion, the highest-leverage opening move is to:", o: ["State a strong position first", "Define terms and propose a structure the group can use", "Wait until others have spoken", "Summarise the topic"], a: 1, e: "It gives the group a structure, signals leadership without dominance, and buys you ownership of the framework everyone then speaks within." },
  { id: "j11", d: "consulting", lvl: 2, q: "If a GD becomes chaotic, the highest-scoring intervention available is to:", o: ["Speak louder to hold the floor", "Say 'we're going in circles - could we agree on the two or three factors that matter and take them one at a time?'", "Stay silent until order returns", "Address the panel directly"], a: 1, e: "A panel notices whoever restores order." },
  { id: "j12", d: "consulting", lvl: 2, q: "A client wants a SOC 2 Type II in three months with no documentation. The right advice is:", o: ["Agree and work faster", "Be honest that a Type II needs an observation period; propose readiness → remediation → Type I → shorter first Type II", "Recommend ISO 27001 instead", "Suggest a self-assessment"], a: 1, e: "And ask what is driving the three months - a Type I plus a documented remediation plan and a committed Type II date frequently satisfies a customer's procurement team." },
  { id: "j13", d: "consulting", lvl: 2, q: "Recommendations are strongest when paired with:", o: ["A vendor recommendation", "A time horizon - short (0-3 months), medium (3-12), long (12-36)", "A cost estimate only", "A framework reference"], a: 1, e: "It demonstrates realism, which is what separates a roadmap from a wish list." },
  { id: "j14", d: "consulting", lvl: 3, q: "A manufacturing client has never done a security assessment. The gap you should specifically expect is:", o: ["Weak password policies", "The OT environment on the shop floor, usually outside the IT security perimeter", "Missing antivirus", "Lack of a firewall"], a: 1, e: "Naming the industry-specific insight is what distinguishes a tailored answer from a generic one." },
  { id: "j15", d: "consulting", lvl: 2, q: "For a first-time security client, the highest-value early recommendations are usually:", o: ["A SIEM and a 24×7 SOC", "Asset inventory, MFA on remote access and email, patching internet-facing systems, backup with a tested restore, and basic logging", "A red team exercise", "ISO 27001 certification"], a: 1, e: "Unglamorous and affordable - and they typically remove more risk than anything sophisticated." },
  { id: "j16", d: "consulting", lvl: 2, q: "You discover an error in your own working paper that is already in a draft report. You should:", o: ["Quietly correct it before anyone notices", "Raise it the same day with the facts: what it is, how it happened, what it affects, what should change", "Wait until the report is finalised", "Mention it in the closing meeting"], a: 1, e: "An unexplained change is worse than the original error. In an audit environment, the mistake is survivable and the cover-up isn't." },
  { id: "j17", d: "consulting", lvl: 2, q: "A finding involves the CFO. The correct handling is to:", o: ["Confront the CFO directly to get the facts", "Document it factually, raise it with your senior and manager the same day, and let leadership decide how it is communicated", "Omit it given the seniority involved", "Reduce the rating to avoid conflict"], a: 1, e: "Establish the facts first - delegated access is legitimate; logging in as the CFO is not. But the finding goes in the file regardless of who it concerns." },
  { id: "j18", d: "consulting", lvl: 2, q: "A SOC report request from a customer's procurement or vendor risk team indicates they want:", o: ["SOC 1 Type I", "SOC 2", "SOC for Supply Chain", "An ISO 27001 certificate"], a: 1, e: "Financial auditors want SOC 1; security and procurement teams want SOC 2." },
  { id: "j19", d: "consulting", lvl: 2, q: "When a Tier 1 vendor refuses to evidence anything and the client cannot replace them, the correct close is:", o: ["Terminate the contract immediately", "Reduce exposure technically and record a documented risk acceptance signed at the right level", "Report them to CERT-In", "Accept the situation informally"], a: 1, e: "So the organisation is making that choice consciously rather than by default." },
  { id: "j20", d: "consulting", lvl: 2, q: "'Inquiry alone is never enough' matters because inquiry only produces:", o: ["An estimate", "An opinion, not evidence", "A preliminary finding", "A scoping input"], a: 1, e: "Pull the review records, check the sign-off dates, verify the revocations were actioned within SLA - that is evidence." },

  /* ============================ HR, ETHICS & FIT ============================ */
  { id: "h01", d: "hrethics", lvl: 1, q: "In a STAR answer, the section that should take roughly 55% of your airtime is:", o: ["Situation", "Task", "Action", "Result"], a: 2, e: "Most candidates invert this - three minutes on situation and ten seconds on action. The action section is the only part that tells them anything about you." },
  { id: "h02", d: "hrethics", lvl: 2, q: "Asked about your greatest weakness, the correct approach is:", o: ["Name a disguised strength like 'I'm a perfectionist'", "Name something real and non-fatal with active mitigation", "Say you have none currently", "Name a weakness irrelevant to the role"], a: 1, e: "\"I tend to over-prepare and can spend too long refining before showing work; I now set a deadline for a first draft and share it early for feedback.\"" },
  { id: "h03", d: "hrethics", lvl: 2, q: "A client offers you an expensive gift. You should:", o: ["Accept it and declare it later", "Decline politely, explain firm policy governs gifts and hospitality, and report it", "Accept it to avoid offence", "Ask your manager whether to accept before responding"], a: 1, e: "Never accept and then ask." },
  { id: "h04", d: "hrethics", lvl: 2, q: "You notice a colleague inflating their timesheet. The correct action is to:", o: ["Confront them directly", "Follow the firm's channel - speak to your manager or use the ethics hotline", "Ignore it as none of your business", "Discuss it with other peers first"], a: 1, e: "Do not confront, do not ignore, do not discuss it with peers." },
  { id: "h05", d: "hrethics", lvl: 2, q: "You realise you emailed a document to the wrong recipient. You should:", o: ["Recall the email and say nothing if successful", "Report it immediately - it may be a data incident with notification obligations", "Wait to see whether the recipient responds", "Delete your copy and move on"], a: 1, e: "Speed matters more than embarrassment, because a notification clock may already be running." },
  { id: "h06", d: "hrethics", lvl: 2, q: "Asked 'are you willing to travel?', the correct answer is:", o: ["A hedged 'it depends on the location'", "An unambiguous yes; disclose any genuine constraint honestly rather than concealing it", "Ask about the travel allowance first", "Say yes but note a strong preference against it"], a: 1, e: "The JD names travel twice. Any hedging here is a real risk to your candidature." },
  { id: "h07", d: "hrethics", lvl: 2, q: "Asked 'what if you are staffed on a non-cyber project?', the best answer:", o: ["Declines politely", "Says yes with grace and a reason - early-career breadth is valuable, with depth built in parallel", "Asks to be reassigned after three months", "Says it would be a deal-breaker"], a: 1, e: "Anything grudging here is a serious negative." },
  { id: "h08", d: "hrethics", lvl: 2, q: "'Why EY?' is answered badly when your answer:", o: ["Mentions the JD", "Would be equally true with a different firm's name substituted", "References a recent development", "Includes a personal reason"], a: 1, e: "Test it that way before the interview. 'EY is one of the Big Four and has a great brand' is an answer to 'why any of the Big Four'." },
  { id: "h09", d: "hrethics", lvl: 2, q: "Your manager asks you to sign off work you haven't completed. You should:", o: ["Sign it, since your manager instructed it", "Clarify first in case of a misunderstanding; if not, decline clearly and escalate", "Refuse and report it externally", "Complete a partial sign-off with a note"], a: 1, e: "The file is evidence and a false sign-off is a professional integrity issue, not an administrative one." },
  { id: "h10", d: "hrethics", lvl: 2, q: "Asked 'how do you keep up with security developments?', vagueness is fatal because it:", o: ["Suggests you lack technical depth", "Contradicts 'inquisitive' in the JD", "Implies you do not read", "Wastes interview time"], a: 1, e: "Name actual sources - vendor threat reports, CERT-In advisories, a newsletter, a framework you have read - then name one thing you learned recently." },
  { id: "h11", d: "hrethics", lvl: 2, q: "Which is a poor question to ask in a first or second round?", o: ["What does an Associate Consultant's first six months look like?", "How does staffing work?", "Is there a lot of overtime?", "Where is demand growing fastest across the JD's areas?"], a: 2, e: "Ask about the rhythm of engagements instead. Also avoid salary, 'how did I do?', and anything answered by the first page of their website." },
  { id: "h12", d: "hrethics", lvl: 2, q: "If a question genuinely stumps you, the best of these responses is:", o: ["A confident guess", "\"I haven't come across that specifically, but let me reason it through from what I do know...\"", "\"I don't know\" and immediate silence", "Changing the subject to a related strength"], a: 1, e: "Interviewers frequently value this more than a correct recalled answer, because it shows them how you think when you do not know. A confident wrong answer is the one outcome that genuinely damages you." },
  { id: "h13", d: "hrethics", lvl: 2, q: "Interviewers probe STAR stories with 'what would you do differently?' and 'who disagreed with you?' primarily to:", o: ["Test memory", "Break fabricated answers - a real story survives all five probes", "Assess vocabulary", "Extend the interview"], a: 1, e: "A well-told story about a college project beats a vague one about an impressive-sounding internship." },
  { id: "h14", d: "hrethics", lvl: 2, q: "You find a serious issue on the last day of fieldwork and reporting it means missing the deadline. You should:", o: ["Carry it to the next audit cycle", "Report it - deadlines move, findings do not disappear - and escalate immediately", "Report it informally to the process owner only", "Reduce the rating so it can be closed quickly"], a: 1, e: "Escalate immediately so leadership can manage the client conversation." },
];
